INSERT INTO releases (version, released_on, title, public_notes, tech_notes) VALUES (
  '2.81.0',
  '2026-09-02',
  'Tracker: набор именованных цветов и градиенты',
  E'В настройках многоцветного трекера теперь собирается набор цветов с названиями — «Бег», «Зал», «Растяжка», до двенадцати. Любой цвет можно сделать градиентом из двух. Названия видны только в настройках: они нужны вам, на отметках не рисуются.\n\nКогда набор задан, под названием трекера появляется строка кружков всего набора. Нажали кружок — им и ставятся отметки; палитра для этого больше не открывается. Если набора нет, всё как раньше: один кружок, клик по нему открывает палитру.\n\nЗаодно починены «последние использованные» цвета в палитре. Раньше там показывалась просто общая палитра пресетов: список последних жил в памяти браузера, а её в Telegram периодически чистит. Теперь сверху идут цвета, которыми вы действительно отмечали дни в этом трекере, свежие первыми.',
  E'tracker_categories.palette JSONB (миграция 0111): [{"color","color2","name"}], до 12 записей, название 1–40 символов, цвета строго #rrggbb. Непустой color2 — градиент.\n\nЦвет отметки (tracker_marks.color) остался строкой, но теперь это либо #rrggbb, либо пара #rrggbb,#rrggbb (markColorRe). Отметка хранит цвет ЦЕЛИКОМ, а не ссылку на запись набора: иначе удаление цвета из набора перекрашивало бы историю задним числом.\n\ncolorCss() в display.ts проверяет значение регуляркой перед подстановкой в style: строка приходит из базы и уезжает в CSS, непроверенной ей там не место. Ячейки, календарь трекера, «вся история» и страница Calendar переведены с backgroundColor на background — градиент в backgroundColor не живёт.\n\nactiveColor() при непустом наборе возвращает только цвет из набора (иначе после удаления цвета отметки ставились бы исчезнувшим). Набор без multi бессмысленен, поэтому добавление цвета включает multi, а галочка блокируется с пояснением.\n\nПочинка «последних»: recentColorsFor(cat) строит список по отметкам трекера (свежие дни первыми) и дополняет списком с устройства. Прежний вариант читал только localStorage — в вебвью Telegram он чистится, список оказывался пустым, и человек видел одну палитру пресетов. Свотчи пикера тоже переведены на colorCss: пара цветов в backgroundColor давала пустой серый квадрат.'
);
-- +goose StatementEnd

